internal object KnowledgeCards {
    val cards: List<LocalKnowledgeCard> = listOf(
        LocalKnowledgeCard(id = "CALL_911", title = "What to tell the emergency call-taker", terms = "911 emergency address location callback ambulance dispatcher", body = "Tell the 911 call-taker your location, callback number, what happened, and the injuries or hazards you can observe. Answer their questions, follow their instructions, and stay on the line until told to hang up. This assistant does not place the call or confirm dispatch.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S01")),
        LocalKnowledgeCard(id = "TEXT_911", title = "Calling versus texting 911", terms = "text deaf hearing speech cannot call emergency", body = "Call 911 by voice if you can. Text-to-911 availability varies; do not assume it works at your location. If you cannot speak, use an available local emergency text option and provide the location and type of emergency.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S02")),
        LocalKnowledgeCard(id = "MOVEMENT", title = "Possible neck back or head injury", terms = "neck back spine spinal hurt get out exit stand walk move injured", body = "With a possible head, neck or back injury, do not move the person simply to make them more comfortable. An immediate safety threat or essential lifesaving care can change what is necessary. Follow emergency-call instructions; do not use an automatic always-exit or always-stay rule.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S04", "S05")),
        LocalKnowledgeCard(id = "BLEEDING", title = "Serious external bleeding", terms = "bleed blood wound bleeding pressure", body = "For life-threatening external bleeding, call 911 and follow emergency instructions. If it is safe to help, apply firm direct pressure to the wound. Do not remove an embedded object; pressure is applied around it. Advanced measures require appropriate training.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S06")),
        LocalKnowledgeCard(id = "HEAD_INJURY", title = "Head injury symptoms and danger signs", terms = "head concussion headache vomiting dizzy dizziness confusion pupil seizure sleepy symptoms", body = "After a possible head injury, worsening headache, repeated vomiting, seizures, unusual confusion or difficulty waking require emergency medical care. Symptoms can appear later. Being able to talk does not establish that someone is uninjured.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S08")),
        LocalKnowledgeCard(id = "FIRE", title = "Vehicle on fire", terms = "fire flames burning smoke car hood trunk", body = "If the vehicle catches fire, get out if you can, stay at least 100 feet away and away from traffic, and call 911. Do not return for belongings, fight the fire yourself or open a hood or trunk where you suspect fire.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S10")),
        LocalKnowledgeCard(id = "EV", title = "Electric and hybrid vehicle damage and towing", terms = "electric hybrid ev high voltage battery tow towing", body = "Damaged electric or hybrid high-voltage systems may remain energized, and fire or hazardous gases can occur later. Do not touch exposed electrical parts or attempt repairs. Tell responders and towing personnel the vehicle type. Follow the correct owner's manual for towing requirements.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S11")),
        LocalKnowledgeCard(id = "CAR_SEAT", title = "Car seat replacement after a collision", terms = "child infant baby booster car seat replace replacement", body = "NHTSA recommends replacing car seats after moderate or severe crashes. A minor-crash exception requires all five conditions: vehicle driven away; nearest door undamaged; no occupant injuries; no deployed airbags; no visible seat damage. Always follow the seat manufacturer's instructions.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S12")),
        LocalKnowledgeCard(id = "CALM_SUPPORT", title = "Support when overwhelmed", terms = "panic scared afraid crying overwhelmed nervous terrified emotional kindness calm", body = "A frightening event can leave people anxious, upset or unable to concentrate. Once immediate safety needs are addressed, focus on one manageable task and consider contacting someone you trust. You do not have to recount the event in detail to receive practical help.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S16", "S13")),
        LocalKnowledgeCard(id = "FOLLOWUP_EMOTION", title = "When to seek emotional support after a crash", terms = "nightmares sleep sleeping flashbacks anxiety trauma ptsd weeks mental health therapist", body = "If distress does not improve, worsens or interferes with daily life, talk with a qualified health professional. Supportive friends or relatives and ordinary routines can help during recovery. This assistant does not diagnose PTSD or provide trauma therapy.", scope = "US", stage = "followup", expires = "2027-01-19", sources = listOf("S16")),
        LocalKnowledgeCard(id = "WA_EXCHANGE", title = "Washington required exchange of information", terms = "wa washington exchange details license policy number name address other driver", body = "In Washington, collision duties include exchanging name, address, insurance company and policy number, vehicle license number, and showing a driver's license as required by RCW 46.52.020. The law also describes stopping, remaining at the appropriate location and providing reasonable assistance to injured people.", scope = "WA", stage = "any", expires = "2027-01-19", sources = listOf("S21")),
        LocalKnowledgeCard(id = "WA_MOVE", title = "Washington moving vehicles after property damage only", terms = "wa washington move moving vehicle traffic lane shoulder property damage only fender bender", body = "Washington's property-damage-only branch requires moving the vehicle from the roadway to a suitable location as soon as possible and remaining there to fulfill the required duties. The statute says moving the vehicle does not determine fault. Injury crashes have a separate branch; do not move an injured person just to reposition a car.", scope = "WA", stage = "any", expires = "2027-01-19", sources = listOf("S21")),
        LocalKnowledgeCard(id = "WA_REPORT", title = "Washington collision report conditions and deadline", terms = "wa washington report reporting file deadline days four 4 1000 thousand officer police paperwork", body = "For qualifying Washington collisions, a driver report is generally due within four days unless a law-enforcement report is to be made. WSP's portal identifies injury or at least \$1,000 damage to any one unit, with an exception when the officer indicates they will file. Confirm that an officer will submit it; attendance alone is not that confirmation.", scope = "WA", stage = "followup", expires = "2027-01-19", sources = listOf("S22", "S23")),
        LocalKnowledgeCard(id = "DOCUMENT", title = "Information and photographs for an insurance claim", terms = "document documentation evidence photographs photos pictures witness weather dashcam plate damage", body = "Once it is safe, record the time, date, location, vehicle information, witness contacts and responding officer or report details. Photograph the scene and damage only from safe positions. Record what you actually observed and distinguish unknown details from estimates.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S29")),
        LocalKnowledgeCard(id = "CLAIM_NOTICE", title = "Notify your insurer and keep a claim record", terms = "insurance notify notification report claim contact adjuster investigation notes receipts", body = "Notify your insurer as soon as possible and cooperate with the claim investigation. Keep notes of conversations, dates and decisions. Ask for written explanations when you do not understand a claim decision.", scope = "US", stage = "followup", expires = "2027-01-19", sources = listOf("S29")),
        LocalKnowledgeCard(id = "STATEMENT", title = "Recorded statement and cooperation questions", terms = "recorded statement recording insurer adjuster refuse never must own other insurance", body = "Before answering a statement request, establish which insurer the person represents and check your own policy's cooperation requirements. A claims investigation may include a written or recorded statement. There is no universal rule to refuse every statement. If obligations or release terms are unclear, seek qualified advice.", scope = "US", stage = "followup", expires = "2027-01-19", sources = listOf("S29", "S30")),
        LocalKnowledgeCard(id = "TRUTHFUL", title = "Accurate accounts and uncertain details", terms = "fault blame admit truth truthful lie lying hide phone using speed guess unsure remember don't know", body = "Describe what you actually saw and did. Do not invent a precise speed, guess at legal responsibility, hide relevant facts or exaggerate injuries. If you do not know a detail, say so; identify a genuine estimate as an estimate and correct mistakes when you discover them.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S29", "S30")),
        LocalKnowledgeCard(id = "COVERAGE", title = "Coverage cannot be inferred from a generic guide", terms = "insurance coverage cover covered policy deductible rental rent tow medical reimbursement benefits", body = "Check the actual policy and endorsements for coverage, exclusions, limits, deductibles and duties after a loss. A generic guide cannot establish that towing, a rental vehicle, repairs or medical costs are covered. Ask the insurer to identify the applicable terms in writing.", scope = "US", stage = "followup", expires = "2027-01-19", sources = listOf("S30")),
        LocalKnowledgeCard(id = "DISPUTE", title = "Disputed settlement or claim decision", terms = "settlement offer deny denied denial dispute unfair pay payout release sign written complaint", body = "You do not need to feel rushed into an insurance settlement you do not understand. Ask for a written explanation of the decision and review the relevant policy terms. If a claim-handling dispute remains unresolved, contact your state insurance department; legal questions may need a qualified lawyer.", scope = "US", stage = "followup", expires = "2027-01-19", sources = listOf("S29")),
        LocalKnowledgeCard(id = "SILENCE", title = "No response does not prove unconsciousness", terms = "silence silent not responding microphone sensor unconscious unconsciousness detection passed out", body = "No response from a phone user does not establish that the person is unconscious. Communication can fail. This prototype cannot determine consciousness or automatically dispatch emergency services; a real system needs separately validated detection and escalation procedures.", scope = "US", stage = "any", expires = "2027-01-19", sources = listOf("S01", "S03")),
        LocalKnowledgeCard(id = "CONCUSSION_RETURN", title = "Driving and work after a concussion", terms = "concussion driving return work school recovery written instructions", body = "After a suspected concussion, seek medical assessment. Ask your healthcare provider for written instructions about returning to driving, work and school. Tell them if symptoms worsen or are not improving; this assistant cannot clear you to drive.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S36")),
        LocalKnowledgeCard(id = "AIRBAG_REPLACE", title = "Deployed air bags need replacement", terms = "airbag air bags deployed deployment replace drive repair", body = "Air bags work only once. Have deployed air bags replaced at an authorized repair center before driving again. Deployment can itself cause injuries; have medical concerns assessed rather than judging injury from vehicle appearance.", scope = "US", stage = "any", expires = "2027-01-20", sources = listOf("S37")),
        LocalKnowledgeCard(id = "AIRBAG_LIMIT", title = "Air bag deployment does not measure injury", terms = "airbag did not deploy no deployment minor collision injury severity", body = "Whether air bags deploy depends on the crash and vehicle system. Air bags may deploy in some relatively minor crashes and may not deploy in others. Their deployment alone cannot establish whether someone is injured or needs medical care.", scope = "US", stage = "any", expires = "2027-01-20", sources = listOf("S37")),
        LocalKnowledgeCard(id = "INTERNAL_BLEED", title = "Delayed or suspected internal bleeding", terms = "internal bleeding delayed abdomen abdominal swollen rigid bruising blood vomit urine", body = "Internal bleeding may become apparent hours or days after an injury. Suspected internal bleeding, including blood in vomit or urine, a tender swollen or rigid abdomen, or signs of shock, needs emergency medical help. Call 911 and describe what you observe; do not wait for visible external bleeding.", scope = "US", stage = "any", expires = "2027-01-20", sources = listOf("S38")),
        LocalKnowledgeCard(id = "CHEST_INJURY", title = "Chest injury and breathing problems", terms = "chest rib ribs injury breathing painful severe bruising coughing blood", body = "After chest trauma, trouble breathing, severe pain or bruising, unusual chest movement, or coughing blood requires immediate emergency medical help. Call 911 and follow the call-taker's instructions. Do not assume these symptoms are anxiety.", scope = "US", stage = "any", expires = "2027-01-20", sources = listOf("S39")),
        LocalKnowledgeCard(id = "ASK_SUPPORT", title = "Ask a trusted person for concrete help", terms = "trusted friend family support help tasks paperwork ride alone isolated", body = "Once immediate safety needs are addressed, consider asking someone you trust for a specific kind of help, such as company or help with paperwork. You can choose whom to involve and explain what would help; support does not require telling everyone the full story.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S40")),
        LocalKnowledgeCard(id = "OPTIONAL_CALM", title = "Calming exercises should be optional", terms = "breathing exercise relaxation meditation makes worse distress stop calming", body = "In a safe setting after the emergency, relaxation may help some people but can initially increase distress for others. Choose a manageable approach and tell a clinician if it makes you feel worse. New physical symptoms after a crash still need medical assessment.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S40")),
        LocalKnowledgeCard(id = "GROUNDING", title = "Present surroundings during a flashback", terms = "grounding flashback reliving memories present surroundings eyes open", body = "In a safe setting, if a memory feels as though it is happening again, keeping your eyes open and noticing your present surroundings may help orient you. Contact a trusted person or clinician for support. This is optional coping support, not a PTSD diagnosis or treatment.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S40")),
        LocalKnowledgeCard(id = "AVOID_SELF_MEDICATING", title = "Alcohol and drugs are not a recovery plan", terms = "alcohol drugs drink sleep self medicate nightmares substance coping", body = "Using alcohol or drugs to escape traumatic memories or get to sleep can create further problems. If you are relying on them to cope, speak with a healthcare professional about support and safer treatment options. This assistant does not prescribe or change medication.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S41")),
        LocalKnowledgeCard(id = "CHILD_SUPPORT", title = "Supporting a child after a crash", terms = "child children teenager teen crying scared parent caregiver trauma comfort", body = "After addressing safety and medical needs, offer a calm, supportive environment and familiar routines. Let a child cry or express feelings in words or drawings. Do not force them to recount the crash, demand bravery, or promise a recovery timeline you cannot know.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S20")),
        LocalKnowledgeCard(id = "CHILD_FOLLOWUP", title = "When a child needs more emotional support", terms = "child nightmares bedwetting school withdrawn behavior weeks provider pediatrician", body = "Watch for new difficulties with sleep, school, behavior or withdrawal after a traumatic event. Contact the child's healthcare provider when new problems develop, especially when distressing reactions continue for weeks. Support is available without asking the app to diagnose the child.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S20")),
        LocalKnowledgeCard(id = "OR_REPORT", title = "Oregon DMV collision report deadlines", terms = "Oregon DMV report reporting deadline 72 hours 2500 police separate", body = "In Oregon, file a DMV collision report within 72 hours for injury or death, damage to your vehicle over \$2,500, damage to any vehicle over \$2,500 with any vehicle towed, or nonvehicle property damage over \$2,500. A police report does not replace this DMV report. If late, submit as soon as possible.", scope = "OR", stage = "followup", expires = "2027-01-20", sources = listOf("S42")),
        LocalKnowledgeCard(id = "OR_FILE", title = "Submitting an Oregon collision report", terms = "Oregon DMV2U online paper form download copy report license ID", body = "Oregon DMV2U online collision reporting requires that you were an involved driver and have an Oregon license, permit or ID number. Otherwise use the paper process. Save a copy of your submitted report; Oregon DMV cannot provide you a copy under the cited rule.", scope = "OR", stage = "followup", expires = "2027-01-20", sources = listOf("S42")),
        LocalKnowledgeCard(id = "OR_SCENE", title = "Oregon scene duties and police notification", terms = "Oregon stop exchange police notify scene information license address plate", body = "In Oregon, stop and exchange name, address, driver-license number, plate and insurance information. Immediately notify police when DMV reporting criteria are met; use a nonemergency number for nonemergencies and 911 for emergencies. Do not carelessly move injured people.", scope = "OR", stage = "any", expires = "2027-01-20", sources = listOf("S42")),
        LocalKnowledgeCard(id = "CA_REPORT", title = "California SR-1 reporting deadline", terms = "California DMV SR1 SR-1 report deadline 10 days 1000 police separate", body = "In California, submit an SR-1 to DMV within 10 days when anyone is injured, however slightly, someone dies, or property damage exceeds \$1,000. This report is separate from police, CHP and insurance reports. A driver, insurance agent, broker or legal representative may submit it.", scope = "CA", stage = "followup", expires = "2027-01-20", sources = listOf("S43")),
        LocalKnowledgeCard(id = "CA_FILE", title = "Information for a California SR-1", terms = "California SR1 DMV form information VIN plate driver license insurance", body = "For California's SR-1, gather your driver-license or ID details, vehicle plate or VIN, insurance details and available information about the other party and vehicle. Use the official DMV process and keep your reporting obligations separate from your insurance claim.", scope = "CA", stage = "followup", expires = "2027-01-20", sources = listOf("S43")),
        LocalKnowledgeCard(id = "WA_UNATTENDED", title = "Washington collision with an unattended car", terms = "Washington parked unattended unoccupied car note owner address", body = "In Washington, if you strike an unattended vehicle, stop immediately. Locate and notify its owner or operator, or leave a conspicuous written notice in the struck vehicle with the names and addresses of both the driver and owner of the striking vehicle. Other reporting duties may also apply.", scope = "WA", stage = "any", expires = "2027-01-20", sources = listOf("S44")),
        LocalKnowledgeCard(id = "REPAIR_ESTIMATE", title = "Written repair estimates and authorization", terms = "repair body shop estimate authorization signed extra charges diagnostic second opinion", body = "Before authorizing repairs, ask for a signed written estimate identifying the repair, parts and labor charges. Ask that the shop obtain approval before exceeding an agreed amount. Ask about diagnostic fees and consider a second opinion for expensive or complicated work; specific legal rights vary by state.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S45")),
        LocalKnowledgeCard(id = "REPAIR_PARTS", title = "Questions about replacement parts", terms = "repair parts OEM aftermarket used salvage remanufactured warranty", body = "Ask what replacement parts the shop proposes and what warranties cover parts and labor. New, remanufactured and salvage parts differ. A certification alone does not guarantee good work; ask about experience with your vehicle's make and model.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S45")),
        LocalKnowledgeCard(id = "COLLISION_COVERAGE", title = "Collision versus liability coverage", terms = "collision liability comprehensive insurance own car damage other person", body = "Collision coverage generally addresses damage to your own car from a collision; liability coverage addresses covered harm you cause to others. Comprehensive coverage generally addresses other specified losses. Your policy, limits, deductibles and exclusions control the actual result; ask your insurer which coverage applies.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S46")),
        LocalKnowledgeCard(id = "GAP_LOAN", title = "A total loss may leave an auto loan balance", terms = "GAP loan finance owe balance totaled total loss actual cash value", body = "A vehicle's value may be less than the loan balance. A vehicle-damage settlement may therefore leave money owed to the lender. Ask whether you purchased GAP coverage and what its terms cover; do not assume ordinary auto insurance pays the entire loan.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S46")),
        LocalKnowledgeCard(id = "UM_UIM", title = "Uninsured and underinsured coverage questions", terms = "uninsured underinsured hit run UM UIM other driver no insurance", body = "Ask your insurer whether you have applicable uninsured or underinsured motorist coverage when the other driver has no insurance or insufficient insurance. Hit-and-run eligibility and reporting requirements depend on the policy and state. Coverage is not established by the other driver's insurance status alone.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S46")),
        LocalKnowledgeCard(id = "RENTAL_TOW", title = "Rental and towing coverage are policy dependent", terms = "rental reimbursement tow towing roadside limits storage receipt coverage", body = "Rental reimbursement and roadside or towing coverage are separate coverage questions. Ask your insurer whether you purchased them, what limits and conditions apply, and what documentation is needed before assuming a bill will be reimbursed.", scope = "US", stage = "followup", expires = "2027-01-20", sources = listOf("S46")),
        LocalKnowledgeCard(id = "WA_PIP", title = "Washington PIP is offered but can be rejected", terms = "Washington PIP personal injury protection offered optional written rejection", body = "Washington law requires PIP to be offered with new or renewed auto liability policies, subject to statutory exceptions. A named insured may reject it in writing, and that rejection may carry forward. Ask your insurer to confirm your coverage and any rejection; PIP is not automatically present on every policy.", scope = "WA", stage = "followup", expires = "2027-01-20", sources = listOf("S47")),
        LocalKnowledgeCard(id = "WA_INSPECTION", title = "Washington photo estimate disagreement", terms = "Washington photo virtual inspection disagreement in person five business days estimate", body = "Under Washington's rule effective October 18, 2026, insurers cannot require a photo-only damage evaluation as a coverage condition. After virtual inspection, if there is a disagreement over the loss amount, they must accept a requested in-person inspection and inspect within five business days or another mutually agreed time.", scope = "WA", stage = "followup", expires = "2027-01-20", sources = listOf("S48")),
        LocalKnowledgeCard(id = "WA_TOW_FEES", title = "Washington written towing and storage coverage explanation", terms = "Washington towing storage fees written explanation five business days first party", body = "Washington's rule effective October 18, 2026 requires an insurer to give a first-party claimant a clear written explanation of applicable storage and towing coverage within five business days of claim notification. This is an explanation requirement, not a promise that every charge is covered.", scope = "WA", stage = "followup", expires = "2027-01-20", sources = listOf("S48")),
        LocalKnowledgeCard(id = "WA_REPAIR_DIFFERENCE", title = "Washington repair estimate differences", terms = "Washington repair estimate difference supplemental damage policy reasons written", body = "In Washington, when an insurer's repair amount differs from your repair estimate, ask for its reasons and relevant policy provisions. The current rule requires explanations for differences and consideration of additional crash-related damage. Choosing a more expensive repair facility may leave you responsible for amounts above the insurer's estimate.", scope = "WA", stage = "followup", expires = "2027-01-20", sources = listOf("S48")),
    )

